sp_widget.client_script:
api.controller = function($scope, $rootScope, $timeout) {
    var c = this;
    c.data = $scope.data;

    $scope.ApplyFilter = function() {
        $scope.data.isLoading = true;
        // MSSOTIQUBE-892 Avoid DOM manipulation use binding instead of document.getElementById
        c.data.own = $scope.data.owningBusiness;

        c.server.update().then(function() {
            $scope.data.isLoading = false;
        });

        // Show loaders
        // $scope.loader = true;
        // $scope.loader1 = true;

        // // Hide loaders after 3 seconds
        // $timeout(function () {
        //     $scope.loader = false;
        //     $scope.loader1 = false;
        // }, 3000);

        // // Show tables after 3 seconds
        // $timeout(function () {
        //     $scope.box3 = true;
        //     $scope.box4 = true;
        // }, 3000);
    };
};

