}

sp_widget.script:
(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */

    var userGr = new GlideRecord('sys_user');
    userGr.addQuery('sys_id', gs.getUserID());
    userGr.query();
    if (userGr.next()) {
        var associatedMarket = userGr.getDisplayValue('u_associated_business_markets');
        if (associatedMarket !== null) {
            data.market = associatedMarket.split(',');
        }
    }

    if (input) {

        // for Opened assigned tasks
        var enc = 'active=true^trade_idISNOTEMPTY^trade_id.settlement_dateISNOTEMPTY^assigned_toISNOTEMPTY^trade_id.owning_business=' + input.own;

        var q1 = enc + '^sys_created_on<=javascript:gs.endOfLastHour()^trade_id.settlement_date<javascript:gs.beginningOfToday()';
        data.count1 = getCount(q1); //last hour pre settlement
        data.q1 = getFinalQuery(q1);

        q1 = enc + '^sys_created_on<=javascript:gs.endOfLastHour()^trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()';
        data.count2 = getCount(q1); //last hour settlement
        data.q2 = getFinalQuery(q1);

        q1 = enc + '^sys_created_on<=javascript:gs.endOfLastHour()^trade_id.settlement_date>javascript:gs.endOfToday()';
        data.count3 = getCount(q1); //last hour post settlement
        data.q3 = getFinalQuery(q1);

        q1 = enc + '^trade_id.high_value_trade=Yes^trade_id.settlement_date<javascript:gs.beginningOfToday()';
        data.count4 = getCount(q1); //high value pre settlement
        data.q4 = getFinalQuery(q1);

        q1 = enc + '^trade_id.high_value_trade=Yes^trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()';
        data.count5 = getCount(q1); //high value settlement
        data.q5 = getFinalQuery(q1);

        q1 = enc + '^trade_id.high_value_trade=Yes^trade_id.settlement_date>javascript:gs.endOfToday()';
        data.count6 = getCount(q1); //high value post settlement
        data.q6 = getFinalQuery(q1);

        q1 = enc + '^trade_id.settlement_date<javascript:gs.beginningOfToday()';
        data.count7 = getCount(q1);//total pre settlement
        data.q7 = getFinalQuery(q1);

        q1 = enc + '^trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()';
        data.count8 = getCount(q1); // total settlement
        data.q8 = getFinalQuery(q1);

        q1 = enc + '^trade_id.settlement_date>javascript:gs.endOfToday()';
		data.count9 = getCount(q1); // total post settlement
        data.q9 = getFinalQuery(q1);

        // for Opened Unassigned tasks
        var encA = 'active=true^trade_idISNOTEMPTY^trade_id.settlement_dateISNOTEMPTY^assigned_toISEMPTY^trade_id.owning_business=' + input.own;

        var qA1 = encA + '^sys_created_on<=javascript:gs.endOfLastHour()^trade_id.settlement_date<javascript:gs.beginningOfToday()';
        data.countA1 = getCount(qA1); //last hour pre settlement
        data.qA1 = getFinalQuery(qA1);

        qA1 = encA + '^sys_created_on<=javascript:gs.endOfLastHour()^trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()';
        data.countA2 = getCount(qA1); //last hour settlement
        data.qA2 = getFinalQuery(qA1);

        qA1 = encA + '^sys_created_on<=javascript:gs.endOfLastHour()^trade_id.settlement_date>javascript:gs.endOfToday()';
        data.countA3 = getCount(qA1); //last hour post settlement
        data.qA3 = getFinalQuery(qA1);

        qA1 = encA + '^trade_id.high_value_trade=Yes^trade_id.settlement_date<javascript:gs.beginningOfToday()';
        data.countA4 = getCount(qA1); //high value pre settlement
        data.qA4 = getFinalQuery(qA1);

        qA1 = encA + '^trade_id.high_value_trade=Yes^trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()';
        data.countA5 = getCount(qA1); //high value settlement
        data.qA5 = getFinalQuery(qA1);

        qA1 = encA + '^trade_id.high_value_trade=Yes^trade_id.settlement_date>javascript:gs.endOfToday()';
        data.countA6 = getCount(qA1); //high value post settlement
        data.qA6 = getFinalQuery(qA1);

        qA1 = encA + '^trade_id.settlement_date<javascript:gs.beginningOfToday()';
        data.countA7 = getCount(qA1); //total pre settlement
        data.qA7 = getFinalQuery(qA1);

        qA1 = encA + '^trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()';
        data.countA8 = getCount(qA1); //total settlement
        data.qA8 = getFinalQuery(qA1);

        qA1 = encA + '^trade_id.settlement_date>javascript:gs.endOfToday()';
        data.countA9 = getCount(qA1); //total post settlement
        data.qA9 = getFinalQuery(qA1);

    }


})();

function getCount(query) {
    var grTask = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
    grTask.addEncodedQuery(query);
    grTask.addAggregate('COUNT');
    grTask.query();
    while (grTask.next()) {
        return grTask.getAggregate('COUNT').toString();
    }
}

function getFinalQuery(ini_query) {
    var instanceName = gs.getProperty('instance_name');
    var instanceURL = 'https://' + instanceName + '.service-now.com/x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_query=';
    return instanceURL + ini_query;
}
